python -c "
import numpy as np
L=open('init.xyz').read().split('\n')[2:98]
S=[l.split()[0] for l in L]; X=np.array([[float(v) for v in l.split()[1:]] for l in L])
D=np.linalg.norm(X[:,None]-X[None],axis=2)
n=len(S)
for i in range(n):
  for j in range(i+1,n):
    if D[i,j]<1.0 or (D[i,j]<1.9 and S[i]!='H' and S[j]!='H' and 'Ir' not in (S[i],S[j]) and D[i,j]>1.6) : print(i,S[i],j,S[j],round(D[i,j],2))
# Ir contacts
for i in (0,1):
  print(i,[(j,S[j],round(D[i,j],2)) for j in range(n) if D[i,j]<2.6 and j!=i])
"
